#!/usr/bin/env python
"""
install_issues_analysis.py  --  add the "Issues — Analysis" charts modal to the
Issues page (fsr.html), with three clickable charts and a drill-down pop-up.

Adds, all wired to the live `issues` table:
  * views/issues.py  -> new `issues_analysis_data` JSON endpoint (appended at end
    of file, with its own @login_required/@permission_required decorators).
  * urls.py          -> route `issues-analysis-data/` (name issues_analysis_data).
  * templates/fsr.html:
      - an "Analysis" button next to "Resolved Issues Report" (desktop row AND
        the mobile "More" menu),
      - the Bootstrap analysis modal: checkbox property filter + From/To year
        range, KPI strip, three tabs (By property / Open-issue aging / Logged vs
        resolved), Chart.js charts, and a drill-down pop-up whose rows link to
        each issue's detail page (new tab).

Design decisions baked in: Resolved = status 'Resolved'; every other status counts
as open (shown in amber); calendar-day basis; monthly time axis; all filtering and
aggregation happen client-side from one JSON payload so charts and drill-downs
always match. Data volume is small so the whole issue list ships once per open.

SAFE: idempotent (per-file marker guards); exact anchors (each verified unique);
`ast.parse` gate on both .py files; template tag + <script> balance gate on the
HTML; preserves CRLF; backups .bak_issanalysis; --dry-run. No migration.

    python install_issues_analysis.py --dry-run
    python install_issues_analysis.py
Then restart the dev server / redeploy, open the Issues page, click "Analysis".
"""
import ast, base64, os, re, sys

DRY='--dry-run' in sys.argv

VIEW_APPEND=''
U_OLD='ICAgIHBhdGgoJ2lzc3VlLWRldGFpbHMvPGludDppc3N1ZV9pZD4vJywgdmlld3MuZ2V0X2lzc3VlX2RldGFpbHMsIG5hbWU9J2dldF9pc3N1ZV9kZXRhaWxzJyks'
U_NEW='ICAgIHBhdGgoJ2lzc3VlLWRldGFpbHMvPGludDppc3N1ZV9pZD4vJywgdmlld3MuZ2V0X2lzc3VlX2RldGFpbHMsIG5hbWU9J2dldF9pc3N1ZV9kZXRhaWxzJyksCiAgICBwYXRoKCdpc3N1ZXMtYW5hbHlzaXMtZGF0YS8nLCB2aWV3cy5pc3N1ZXNfYW5hbHlzaXNfZGF0YSwgbmFtZT0naXNzdWVzX2FuYWx5c2lzX2RhdGEnKSw='
B1_OLD='ICAgICAgICA8YnV0dG9uIGNsYXNzPSJidG4gYnRuLWluZm8gYWN0aW9uLXNlY29uZGFyeSIgZGF0YS10b2dnbGU9Im1vZGFsIiBkYXRhLXRhcmdldD0iI2RhdGVSYW5nZU1vZGFsIj4KICAgICAgICAgICAgUmVzb2x2ZWQgSXNzdWVzIFJlcG9ydAogICAgICAgIDwvYnV0dG9uPg=='
B1_NEW=''
B2_OLD=''
B2_NEW=''
BLK_OLD='PC9zY3JpcHQ+Cgp7JSBlbmRibG9jayAlfQ=='
BLK_NEW=''

def read(p):
    with open(p,encoding='utf-8') as f: return f.read()
def detect_nl(p):
    with open(p,'rb') as f: return '\r\n' if f.read().count(b'\r\n') else '\n'
def write(p,s,nl):
    with open(p,'w',encoding='utf-8',newline=nl) as f: f.write(s)
def d(b): return base64.b64decode(b).decode()
def tagbal(t):
    P=[(r'{%\s*if\b',r'{%\s*endif\s*%}'),(r'{%\s*for\b',r'{%\s*endfor\s*%}'),(r'{%\s*block\b',r'{%\s*endblock\s*%}')]
    return all(len(re.findall(a,t))==len(re.findall(b,t)) for a,b in P)

def main():
    root=os.getcwd()
    if not os.path.exists(os.path.join(root,'manage.py')):
        print('!! Run from the project root (where manage.py lives).'); sys.exit(1)
    view=os.path.join(root,'pages','views','issues.py')
    urls=os.path.join(root,'pages','urls.py')
    tpl=os.path.join(root,'pages','templates','fsr.html')
    for p in (view,urls,tpl):
        if not os.path.exists(p): print('!! missing',p); sys.exit(1)

    changed=[]

    # ---- view: append endpoint ----
    vt=read(view)
    if 'def issues_analysis_data' in vt:
        print('[skip] issues.py already has issues_analysis_data.'); v_new=None
    else:
        v_new=vt+d(VIEW_APPEND)
        try: ast.parse(v_new)
        except SyntaxError as e: print('!! issues.py would not parse (%s). Nothing changed.'%e); sys.exit(1)
        changed.append('views/issues.py')

    # ---- urls ----
    ut=read(urls)
    if "name='issues_analysis_data'" in ut:
        print('[skip] urls.py already has the route.'); u_new=None
    else:
        o,n=d(U_OLD),d(U_NEW)
        if ut.count(o)!=1: print('!! urls anchor not found exactly once (%d).'%ut.count(o)); sys.exit(1)
        u_new=ut.replace(o,n,1)
        try: ast.parse(u_new)
        except SyntaxError as e: print('!! urls.py would not parse (%s). Nothing changed.'%e); sys.exit(1)
        changed.append('urls.py')

    # ---- fsr.html ----
    ft=read(tpl)
    if 'id="issuesAnalysisModal"' in ft:
        print('[skip] fsr.html already has the analysis modal.'); f_new=None
    else:
        for lbl,ob in (('desktop button',B1_OLD),('mobile menu item',B2_OLD),('endblock',BLK_OLD)):
            if ft.count(d(ob))!=1:
                print('!! fsr.html anchor "%s" not found exactly once (%d). Nothing changed.'%(lbl,ft.count(d(ob)))); sys.exit(1)
        f_new=ft.replace(d(B1_OLD),d(B1_NEW),1).replace(d(B2_OLD),d(B2_NEW),1).replace(d(BLK_OLD),d(BLK_NEW),1)
        if not tagbal(f_new): print('!! fsr.html template tag balance broke. Nothing changed.'); sys.exit(1)
        if f_new.count('<script')!=f_new.count('</script>'): print('!! fsr.html <script> balance broke. Nothing changed.'); sys.exit(1)
        changed.append('templates/fsr.html')

    if not changed:
        print(''); print('[nothing to do] already installed.'); return
    if DRY:
        print(''); print('[dry-run] would update: '+', '.join(changed)); return

    if v_new is not None:
        nl=detect_nl(view); bak=view+'.bak_issanalysis'
        if not os.path.exists(bak): write(bak,read(view),nl)
        write(view,v_new,nl); print('[OK] views/issues.py (.bak_issanalysis)')
    if u_new is not None:
        nl=detect_nl(urls); bak=urls+'.bak_issanalysis'
        if not os.path.exists(bak): write(bak,read(urls),nl)
        write(urls,u_new,nl); print('[OK] urls.py (.bak_issanalysis)')
    if f_new is not None:
        nl=detect_nl(tpl); bak=tpl+'.bak_issanalysis'
        if not os.path.exists(bak): write(bak,read(tpl),nl)
        write(tpl,f_new,nl); print('[OK] templates/fsr.html (.bak_issanalysis)')

    print(''); print('Installed. Restart the dev server / redeploy, open the Issues page and click "Analysis".')

if __name__=='__main__':
    main()